export function OfficialIcon({
  name,
  weight = "Regular",
  size = 24,
  className,
  ...props
}: {
  name: OfficialIconName;
  weight?: MiuixIconWeight;
  size?: number;
  className?: string;
} & Omit<SVGProps<SVGSVGElement>, "name">) {
  const icon = OFFICIAL_ICONS[weight][name];
  return (
    <svg
      aria-hidden
      className={className}
      width={size}
      height={size}
      viewBox={icon.viewBox}
      fill="currentColor"
      focusable="false"
      {...props}
    >
      <g transform={`translate(0 ${icon.height}) scale(1 -1)`}>
        {icon.paths.map((d, index) => (
          <path key={index} d={d} />
        ))}
      </g>
    </svg>
  );
}
